package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io/fs"
	"maps"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

// The frontend is embedded into production builds without touching the
// project: `go build -overlay` adds a generated file to the app's package
// that embeds the frontendDist files, which the overlay maps into a
// directory of the package, and hands them to SetFrontend of package protocol
// (mygo.SetFrontend, in the MyGo of apps that pin one without that package).
// The names of the generated files start with 0 to sort before the app's own:
// the go tool presents the files in the order of their names, and so runs
// their init functions, and a SetFrontend of the app's must come after the
// generated one to win.
const (
	frontendGenFile = "0mygo_frontend_gen.go"
	frontendGenDir  = "mygo_frontend"
)

const frontendGenSource = `// Code generated by mygo build. DO NOT EDIT.

package main

import (
	"embed"
	"io/fs"

	"{{package}}"
)

//go:embed all:` + frontendGenDir + `
var mygoFrontendFiles embed.FS

func init() {
	files, _ := fs.Sub(mygoFrontendFiles, "` + frontendGenDir + `")
	{{setFrontend}}(files)
}
`

// `mygo dev` serves the frontendDist files from disk when it has no dev
// server (MYGO_FRONTEND_DIST), so that edits show on reload. An app links the
// code that serves mygo:// only when it imports package protocol and calls
// protocol.SetFrontend, so the dev build adds a file, through the same
// overlay, that calls it with those files.
const devFrontendGenFile = "0mygo_devfrontend_gen.go"

const devFrontendGenSource = `// Code generated by mygo dev. DO NOT EDIT.

package main

import (
	"os"

	"{{package}}"
)

func init() {
	if dir := os.Getenv("MYGO_FRONTEND_DIST"); dir != "" {
		{{setFrontend}}(os.DirFS(dir))
	}
}
`

const protocolPackage = "github.com/egoist/mygo/protocol"

// frontendSource fills in a generated source that sets the frontend: package
// protocol's SetFrontend, or mygo.SetFrontend in the MyGo of an app that pins
// one without package protocol (before SetFrontend moved), which is what it
// had then. An app whose MyGo cannot be found, or whose vendor directory lacks
// the package, stops the build with the reason (appHasPackage).
func frontendSource(c *Config, source string) (string, error) {
	has, err := appHasPackage(c, protocolPackage)
	if err != nil {
		return "", err
	}
	pkg, call := mygoModule, "mygo.SetFrontend"
	if has {
		pkg, call = protocolPackage, "protocol.SetFrontend"
	}
	return strings.NewReplacer("{{package}}", pkg, "{{setFrontend}}", call).Replace(source), nil
}

// devServesFrontendDist reports whether `mygo dev` serves frontendDist from
// disk: it has no dev server to point the app at.
func devServesFrontendDist(c *Config) bool { return c.DevURL == "" && c.FrontendDist != "" }

// devFrontendFiles returns the overlay entries that make the dev build of the
// app in pkg serve MYGO_FRONTEND_DIST, writing the generated source into
// work. It returns nothing when `mygo dev` does not serve frontendDist.
func devFrontendFiles(c *Config, pkg, work string) (map[string]string, error) {
	replace := map[string]string{}
	if !devServesFrontendDist(c) {
		return replace, nil
	}
	if _, err := os.Lstat(filepath.Join(pkg, devFrontendGenFile)); err == nil {
		return nil, fmt.Errorf("%s is in the way of serving the frontend; rename it", filepath.Join(pkg, devFrontendGenFile))
	}
	src, err := frontendSource(c, devFrontendGenSource)
	if err != nil {
		return nil, err
	}
	gen := filepath.Join(work, devFrontendGenFile)
	if err := os.WriteFile(gen, []byte(src), 0o644); err != nil {
		return nil, err
	}
	replace[filepath.Join(pkg, devFrontendGenFile)] = gen
	return replace, nil
}

// An app with updates in mygo.config.ts needs the HTTP feed of mygo.Updater,
// which package mygo does not link (importing net/http costs an app 2.2
// MB): the build adds a file that imports it, through the same overlay.
const updateFeedGenFile = "0mygo_updates_gen.go"

const updatefeedPackage = "github.com/egoist/mygo/updatefeed"

const updateFeedGenSource = `// Code generated by mygo build. DO NOT EDIT.

package main

import _ "github.com/egoist/mygo/updatefeed"
`

// mygoModule is the module of MyGo, which the app requires.
const mygoModule = "github.com/egoist/mygo"

// appHasPackage reports whether the MyGo that the app at c.root builds with
// has the package path, a package of MyGo's module. The files the CLI
// generates import packages of the CLI's version of MyGo; an app whose go.mod
// pins an older one does not have them, and the build would fail in a file
// the user did not write, with advice (go get) that cannot fix it: such an app
// is built as it was, with what its MyGo gives it.
//
// It says so only when it is sure the package is not there. When it cannot
// find the module (a go.mod that does not parse, a module that cannot be
// loaded, GOFLAGS=-mod=vendor without a consistent vendor directory, no
// network) it returns go's own error, so that the build fails with its reason
// and does not leave out a file the release needs. In an app that builds from a
// vendor directory, a package that is not in it is an error too: it may be one
// MyGo has and the vendor directory lacks (go mod vendor copies what the app's
// code imports, not what this build adds), and nothing here can tell.
//
// An app builds from its vendor directory when -mod=vendor is in effect
// (GOFLAGS or go env -w), or when no -mod is and vendor/modules.txt is next
// to go.mod (go 1.14 and later). Otherwise the module is where go list -m says;
// when it says none because the module is not in the cache yet, go list on
// the package fetches it as a build would and tells.
//
// The answers that are not errors are remembered for the run of the CLI, while
// go.mod, go.sum and vendor/modules.txt stay as they were: a live-reloading
// `mygo dev` builds again at every change of the app.
func appHasPackage(c *Config, path string) (bool, error) {
	key := c.root + "\x00" + path
	pkgChecks.Lock()
	known, ok := pkgChecks.m[key]
	pkgChecks.Unlock()
	if ok && known.fingerprint == fingerprint(known.files) {
		return known.has, nil
	}
	gomodOut, err := goOutput(c.root, "env", "GOMOD")
	if err != nil {
		return false, fmt.Errorf("finding the go.mod of the app: %w", err)
	}
	gomod := strings.TrimSpace(gomodOut)
	if gomod == "" || gomod == os.DevNull {
		return false, fmt.Errorf("%s is not in a Go module", c.root)
	}
	root := filepath.Dir(gomod)
	files := []string{gomod, filepath.Join(root, "go.sum"), filepath.Join(root, "vendor", "modules.txt")}
	before := fingerprint(files)

	var has bool
	if vendorMode(c.root, root) {
		has, err = hasInVendor(root, path)
	} else {
		has, err = hasInModule(c.root, path)
	}
	if err != nil {
		return false, err
	}
	pkgChecks.Lock()
	pkgChecks.m[key] = pkgCheck{has: has, files: files, fingerprint: before}
	pkgChecks.Unlock()
	return has, nil
}

// pkgChecks remembers what appHasPackage found, for fingerprint(files) to
// stay as it was.
var pkgChecks = struct {
	sync.Mutex
	m map[string]pkgCheck
}{m: map[string]pkgCheck{}}

type pkgCheck struct {
	has         bool
	files       []string
	fingerprint string
}

// fingerprint is what stat says of files: it changes when one is written.
func fingerprint(files []string) string {
	var b strings.Builder
	for _, f := range files {
		if fi, err := os.Stat(f); err == nil {
			fmt.Fprintf(&b, "%s:%d:%d;", f, fi.Size(), fi.ModTime().UnixNano())
		} else {
			fmt.Fprintf(&b, "%s:-;", f)
		}
	}
	return b.String()
}

// vendorMode reports whether the app, whose go.mod is in root, builds from its
// vendor directory.
func vendorMode(dir, root string) bool {
	mod := ""
	for _, f := range goFlags(dir) {
		if v, ok := strings.CutPrefix(strings.TrimLeft(f, "-"), "mod="); ok {
			mod = v // the last one wins
		}
	}
	if mod != "" {
		return mod == "vendor"
	}
	_, err := os.Stat(filepath.Join(root, "vendor", "modules.txt"))
	return err == nil
}

// hasInVendor looks for the package in the vendor directory in root.
func hasInVendor(root, path string) (bool, error) {
	vendor := filepath.Join(root, "vendor")
	if _, err := os.Stat(filepath.Join(vendor, "modules.txt")); err != nil {
		return false, fmt.Errorf("the app builds from a vendor directory, and %s has no modules.txt: run go mod vendor, or build without vendoring (-mod=mod)", vendor)
	}
	if hasGoFiles(filepath.Join(vendor, filepath.FromSlash(path))) {
		return true, nil
	}
	return false, fmt.Errorf("the vendor directory of the app, %s, has no %s, which this build needs, and go mod vendor copies only packages the app's code imports (not the ones this build adds): add import _ %q to a file of the app (main.go), run go get %s@latest if its MyGo is older than this CLI, and go mod vendor; or build without vendoring", vendor, path, path, mygoModule)
}

// hasInModule asks go where the app's MyGo is and looks for the package in
// it.
func hasInModule(dir, path string) (bool, error) {
	out, err := goOutput(dir, "list", "-m", "-f", "{{.Dir}}", mygoModule)
	if err != nil {
		return false, fmt.Errorf("finding the MyGo of the app: %w", err)
	}
	if moduleDir := strings.TrimSpace(out); moduleDir != "" {
		return hasGoFiles(filepath.Join(moduleDir, filepath.FromSlash(strings.TrimPrefix(path, mygoModule+"/")))), nil
	}
	// The module is not in the module cache yet, so it has no directory.
	// go list on the package fetches it, as the build would, and says whether
	// the package is there; only go's "does not contain package" is a no.
	out, err = goOutput(dir, "list", "-e", "-f", "{{if .Error}}{{.Error.Err}}{{else}}ok{{end}}", path)
	if err != nil {
		return false, fmt.Errorf("finding the MyGo of the app: %w", err)
	}
	switch said := strings.TrimSpace(out); {
	case said == "ok":
		return true, nil
	case strings.Contains(said, "does not contain package"):
		return false, nil
	default:
		return false, fmt.Errorf("finding %s in the MyGo of the app: %s", path, said)
	}
}

// goOutput runs go in dir and returns what it printed; its error holds what
// go said on stderr.
func goOutput(dir string, args ...string) (string, error) {
	var out, errOut bytes.Buffer
	cmd := goCommand(dir, nil, args...)
	cmd.Stdout, cmd.Stderr = &out, &errOut
	if err := cmd.Run(); err != nil {
		if msg := strings.TrimSpace(errOut.String()); msg != "" {
			return "", fmt.Errorf("go %s: %w\n%s", strings.Join(args, " "), err, msg)
		}
		return "", fmt.Errorf("go %s: %w", strings.Join(args, " "), err)
	}
	return out.String(), nil
}

// hasGoFiles reports whether dir holds the source of a package.
func hasGoFiles(dir string) bool {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false
	}
	for _, e := range entries {
		if n := e.Name(); !e.IsDir() && strings.HasSuffix(n, ".go") && !strings.HasSuffix(n, "_test.go") {
			return true
		}
	}
	return false
}

// updateFeedFiles returns the overlay entry that links the HTTP feed of the
// updates into the main package in pkg, writing the generated source into
// work. It returns nothing when the app has no updates, or its MyGo has no
// updatefeed (an older one fetches the feed by itself).
func updateFeedFiles(c *Config, pkg, work string) (map[string]string, error) {
	replace := map[string]string{}
	if c.Updates == nil {
		return replace, nil
	}
	has, err := appHasPackage(c, updatefeedPackage)
	if err != nil {
		return nil, err
	}
	if !has {
		logf("The MyGo of this app has no %s; its updates use the feed it has. Update MyGo (go get github.com/egoist/mygo@latest) to build as this CLI does.", updatefeedPackage)
		return replace, nil
	}
	if _, err := os.Lstat(filepath.Join(pkg, updateFeedGenFile)); err == nil {
		return nil, fmt.Errorf("%s is in the way of linking the update feed; rename it", filepath.Join(pkg, updateFeedGenFile))
	}
	gen := filepath.Join(work, updateFeedGenFile)
	if err := os.WriteFile(gen, []byte(updateFeedGenSource), 0o644); err != nil {
		return nil, err
	}
	replace[filepath.Join(pkg, updateFeedGenFile)] = gen
	return replace, nil
}

// frontendFiles returns the overlay entries that embed FrontendDist into
// the main package in pkg, writing the generated source into work. It
// returns nothing when the app has no frontend to embed.
func frontendFiles(c *Config, pkg, work string) (map[string]string, error) {
	replace := map[string]string{}
	if c.FrontendDist == "" {
		return replace, nil
	}
	dist := c.path(c.FrontendDist)
	for _, name := range []string{frontendGenFile, frontendGenDir} {
		if _, err := os.Lstat(filepath.Join(pkg, name)); err == nil {
			return nil, fmt.Errorf("%s is in the way of embedding the frontend; rename it", filepath.Join(pkg, name))
		}
	}
	err := filepath.WalkDir(dist, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() || !d.Type().IsRegular() {
			return nil
		}
		rel, err := filepath.Rel(dist, path)
		if err != nil {
			return err
		}
		replace[filepath.Join(pkg, frontendGenDir, rel)] = path
		return nil
	})
	if os.IsNotExist(err) {
		return nil, fmt.Errorf("frontendDist %s does not exist; set buildCommand in %s to build it", c.FrontendDist, c.configName())
	}
	if err != nil {
		return nil, err
	}
	if len(replace) == 0 {
		return nil, fmt.Errorf("frontendDist %s is empty", c.FrontendDist)
	}
	gen := filepath.Join(work, frontendGenFile)
	src, err := frontendSource(c, frontendGenSource)
	if err != nil {
		return nil, err
	}
	if err := os.WriteFile(gen, []byte(src), 0o644); err != nil {
		return nil, err
	}
	replace[filepath.Join(pkg, frontendGenFile)] = gen
	return replace, nil
}

// mergeFiles returns the overlay entries of both maps.
func mergeFiles(a, b map[string]string) map[string]string {
	out := maps.Clone(a)
	if out == nil {
		out = map[string]string{}
	}
	maps.Copy(out, b)
	return out
}

// writeOverlay writes a go build -overlay file, or returns "" when there is
// nothing to overlay.
func writeOverlay(path string, replace map[string]string) (string, error) {
	if len(replace) == 0 {
		return "", nil
	}
	data, err := json.Marshal(struct{ Replace map[string]string }{replace})
	if err != nil {
		return "", err
	}
	return path, os.WriteFile(path, data, 0o644)
}

// packageDir returns the directory of the app's main package.
func packageDir(c *Config) (string, error) {
	var out bytes.Buffer
	cmd := goCommand(c.root, nil, "list", "-f", "{{.Dir}}", c.Main)
	cmd.Stdout = &out
	if err := cmd.Run(); err != nil {
		return "", fmt.Errorf("go list %s: %w", c.Main, err)
	}
	return strings.TrimSpace(out.String()), nil
}
